                }

                Div(attrs = {
                    style {
                        display(DisplayStyle.Flex)
                        flexDirection(FlexDirection.Row)
                        gap(12.px)
                        width(100.percent)
                    }
                }) {
                    Div(attrs = { style { flex(1) } }) {
                        CustomNumberInput("میزان سرکاری", inputState.sarkari.mizan) { v -> viewModel.updateSarkari { it.copy(mizan = v) } }
